app = Flask(__name__)

@app.route("/ls")
def ls():
    # Get a directory name from request
    dirname = request.args.get('dirname', '.')

    # Ensure the directory exists to avoid running the command on a non-existent directory
    if not os.path.isdir(dirname):
        return jsonify({"error": "Directory does not exist."}), 404

    # Construct a "ls" command to list the contents of "dirname"
    try:
        # Run the command
        result = subprocess.run(['ls', '-l', dirname], capture_output=True, text=True, check=True)
        # Return the output
        return jsonify({"output": result.stdout.splitlines()}), 200
    except subprocess.CalledProcessError as e:
        return jsonify({"error": "Failed to list directory contents.", "details": str(e)}), 500
    except Exception as e:
        return jsonify({"error": "An unexpected error occurred.", "details": str(e)}), 500

if __name__ == "__main__":
    app.run(debug=True)

