char **stringArray = NULL;
size_t stringCount = 0;

void pushString(const char *str)
{
    char **newArray = realloc(stringArray, (stringCount + 1) * sizeof(char *));
    if (newArray == NULL)
    {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    stringArray = newArray;
    stringArray[stringCount] = malloc(strlen(str) + 1);
    if (stringArray[stringCount] == NULL)
    {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    strncpy(stringArray[stringCount], str, strlen(str) + 1);
    stringCount++;
}

int pushStrings(char *firstString, ...)
{
    va_list args;
    char *arg;
    int count = 0;

    va_start(args, firstString);

    // process inputs, beginning with firstString
    // ending when NULL is reached
    arg = firstString;
    while (arg != NULL)
    {
        // push the string
        pushString(arg);
        // increment count
        count++;
        // move on to the next input
        arg = va_arg(args, char *);
    }

    va_end(args);

    return count; // return the number of strings pushed
}

int main(int argc, char *argv[])
{
    // push the strings: "apple", "pear", "banana"
    pushStrings("apple", "pear", "banana", NULL);

    // then print each string in the stringArray
    for (size_t i = 0; i < stringCount; i++)
    {
        printf("%s\n", stringArray[i]);
        free(stringArray[i]); // free each individual string
    }

    free(stringArray); // free the array itself

    return 0;
}

