int main(int argc, char *argv[])
{
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    int fd = open(argv[1], O_RDONLY);

    if (fd == -1)
    {
        perror("Open failed");
        return 1;
    }

    char buf[BUF_SIZE];
    char cpy[BUF_SIZE];

    ssize_t numRead = read(fd, buf, BUF_SIZE - 1);

    if (numRead == -1)
    {
        perror("Read failed");
        close(fd);
        return 1;
    }

    // Null-terminate the buffer to make it a valid string
    buf[numRead] = '\0';

    // Copy the contents from buf to cpy
    strncpy(cpy, buf, BUF_SIZE);

    // Print the content of cpy
    printf("Content read and copied:\n%s", cpy);

    // Close the file descriptor
    close(fd);
    return 0;
}

