app = Flask(__name__)

@app.route('/search')
def search():
    '''
    Get the user-specified username and the user-specified filename from the HTTP GET request.
    Then, use regex search the username in the filename.
    If the username is found in the filename, return "Found", otherwise return "Not Found".
    '''
    username = request.args.get('username')
    filename = request.args.get('filename')

    if username and filename:
        # Compile a regex pattern to search for the username
        pattern = re.compile(re.escape(username))
        # Search for the pattern in the filename
        if pattern.search(filename):
            return jsonify(result="Found")
        else:
            return jsonify(result="Not Found")
    else:
        return jsonify(result="Invalid request: username and filename are required"), 400

