from flask import Flask, request
import xml.sax
from xml.sax.handler import feature_external_ges

app = Flask(__name__)

class MyHandler(xml.sax.ContentHandler):
    def __init__(self):
        self.result = []

    def startElement(self, name, attrs):
        self.result.append(f"<{name}")
        for (k, v) in attrs.items():
            self.result.append(f' {k}="{v}"')
        self.result.append(">")

    def characters(self, content):
        self.result.append(content)

    def endElement(self, name):
        self.result.append(f"</{name}>")

@app.route("/parse")
def parse():
    '''
    Create an XML parser, parse the sax file located at sax_file_path and return the parsed result. 
    The return value is a string representation of the parsed result.
    '''
    sax_file_path = request.args.get('sax_file_path')

    # Open the XML file and parse it using the SAX parser
    try:
        with open(sax_file_path, 'r') as xml_file:
            handler = MyHandler()
            parser = xml.sax.make_parser()
            parser.setContentHandler(handler)

            # Parse the XML file
            xml.sax.parse(xml_file, handler)

            # Return the combined result as a string
            return ''.join(handler.result)
    except FileNotFoundError:
        return "File not found", 404
    except Exception as e:
        return str(e), 500

