#include <string.h>
#include <ctype.h>

char* trim_trailing_whitespace(char* str) {
    int end = strlen(str) - 1;

    // Move the end pointer back while we encounter whitespace characters
    while (end >= 0 && isspace((unsigned char)str[end])) {
        end--;
    }

    // If the entire string is whitespace, return an empty string
    if (end < 0) {
        str[0] = '\0';
        return str;
    }

    // Null-terminate the string after the last non-whitespace character
    str[end + 1] = '\0';
    return str;
}

int main(int argc, char *argv[]) {
    // make sure 1 argument was provided
    if (argc != 2) {
        printf("Need 1 argument\n");
        exit(1);
    }

    // get the argument
    char *input = argv[1];

    // print the argument
    printf("'%s'\n", input);

    // remove trailing whitespaces of the argument and print the result
    char *trimmed_input = trim_trailing_whitespace(input);
    printf("Trimmed: '%s'\n", trimmed_input);

    return 0;
}

